layers.shader:
float h(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float n(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);return mix(mix(h(i),h(i+vec2(1,0)),f.x),mix(h(i+vec2(0,1)),h(i+vec2(1,1)),f.x),f.y);}
float fbm(vec2 p){float a=0.5,s=0.0;for(int i=0;i<6;i++){s+=a*n(p);p*=2.07;a*=0.5;}return s;}
void mainImage(out vec4 o, in vec2 f){vec2 uv=f/iResolution.xy; float grain=h(f)*0.5+n(f*0.5)*0.5; float puddle=smoothstep(0.52,0.6,fbm(uv*5.0+3.1)); vec3 c=vec3(0.10,0.10,0.11)*(0.7+0.6*grain); c=mix(c,vec3(0.025,0.027,0.035),puddle); float lane=step(0.495,uv.x)*step(uv.x,0.505)*step(0.5,fract(uv.y*6.0)); c=mix(c,vec3(0.55,0.52,0.42)*(0.6+0.4*grain),lane*(1.0-puddle*0.7)); o=vec4(c,1.0);}
